using Azure.Data.Tables;
using Azure;

var serviceClient = new TableServiceClient("<connection-string>");
var tableClient = serviceClient.GetTableClient("UserProfiles");
await tableClient.CreateIfNotExistsAsync();

var entity = new TableEntity(partitionKey: "user-101", rowKey: "profile")
{
  { "DisplayName", "Ada Lovelace" },
  { "Email", "ada@example.com" },
  { "Country", "UK" }
};

await tableClient.AddEntityAsync(entity);
